ValidationRule.errorConditionFormula:
OR(
    AND(
        ISPICKVAL(Site_Visit_Status__c, "Confirmed"),
        OR(
            ISBLANK(Confirmed_Site_Visit_Date__c),
            ISBLANK(Site_Visit_Time__c)
        )
    ),
    AND(
        NOT(ISPICKVAL(Site_Visit_Status__c, "Confirmed")),
        OR(
            NOT(ISBLANK(Confirmed_Site_Visit_Date__c)),
            NOT(ISBLANK(Site_Visit_Time__c))
        )
    )
)
